/*
 * The classifynext block: finds the next protocol and records it at
 * previous_index + 1. A case that sets no nextencaps classifies nothing.
 */
static mmt_classify_verdict_t ethernet_example_classify_next(ipacket_t *ipacket, unsigned previous_index)
{
    classified_proto_t next;
    int ok = 1;
    int classified = 0;
    int64_t offset = 0;
    int64_t subject = ethernet_example_val_h_proto(ipacket, previous_index, &ok);

    if (!ok) {
        return MMT_CLASSIFY_SKIP;
    }
    memset(&next, 0, sizeof(next));
    switch (subject) {
    case 2048: /* ETH_P_IP */
        next.proto_id = 178; /* NEXT_IP */
        classified = 1;
        offset = 14;
        break;
    case 2054: /* ETH_P_ARP */
        next.proto_id = 30; /* NEXT_ARP */
        classified = 1;
        offset = 14;
        break;
    case 34525: /* ETH_P_IPV6 */
        next.proto_id = 182; /* NEXT_IPV6 */
        classified = 1;
        offset = 14;
        break;
    case 32821: /* ETH_P_RARP */
        next.proto_id = 30; /* NEXT_ARP */
        classified = 1;
        offset = 14;
        break;
    }
    if (!ok || !classified || offset < 0 || offset > UINT16_MAX) {
        return MMT_CLASSIFY_SKIP;
    }
    next.offset = (uint16_t) offset;
    next.status = Classified;
    if (!set_classified_proto(ipacket, previous_index + 1, next)) {
        return MMT_CLASSIFY_SKIP;
    }
    return MMT_CLASSIFY_MATCHED;
}

