int init_ethernet_example_proto_struct(void)
{
    protocol_t *protocol_struct;
    size_t i;

    /* mmt-dpi ignores a protocol name that is already registered (names
     * compare case-insensitively): refuse to load instead. */
    if (get_protocol_id_by_name(PROTO_ETHERNET_EXAMPLE_ALIAS) != 0) {
        mmt_log_error("init_ethernet_example_proto_struct: protocol name %s is already registered", PROTO_ETHERNET_EXAMPLE_ALIAS);
        return 0;
    }
    protocol_struct = init_protocol_struct_for_registration(PROTO_ETHERNET_EXAMPLE, PROTO_ETHERNET_EXAMPLE_ALIAS);
    if (protocol_struct == NULL) {
        mmt_log_error("init_ethernet_example_proto_struct: protocol id %d is out of range or already registered", PROTO_ETHERNET_EXAMPLE);
        return 0;
    }
    for (i = 0; i < sizeof(ethernet_example_attributes_metadata) / sizeof(ethernet_example_attributes_metadata[0]); i++) {
        if (!register_attribute_with_protocol(protocol_struct, &ethernet_example_attributes_metadata[i])) {
            mmt_log_error("init_ethernet_example_proto_struct: cannot register attribute %s", ethernet_example_attributes_metadata[i].alias);
            return 0;
        }
    }
    if (!register_classification_function(protocol_struct, ethernet_example_classify_next)) {
        mmt_log_error("init_ethernet_example_proto_struct: cannot register the classify_next function");
        return 0;
    }
    if (!register_protocol(protocol_struct, PROTO_ETHERNET_EXAMPLE)) {
        mmt_log_error("init_ethernet_example_proto_struct: cannot register protocol %d", PROTO_ETHERNET_EXAMPLE);
        return 0;
    }
    /* User code (src/ethernet_example_impl.c) attaches the protocol to its parents. */
    if (!ethernet_example_hook_register_parents(protocol_struct)) {
        mmt_log_error("init_ethernet_example_proto_struct: ethernet_example_hook_register_parents() failed");
        return 0;
    }
    return 1;
}

